def transform(grid):
    # Exact-cover the pattern with 2x2 squares and L triominoes. The demo
    # output uses color 1 for squares, and colors 2/3/4 for L orientations:
    # missing top-left=2, bottom-left=3, top-right=4.
    h,w=len(grid),len(grid[0]); cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    out=[[0]*w for _ in range(h)]; placements=[]
    for r in range(h-1):
      for c in range(w-1):
        box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if box<=cells: placements.append((box,1,0))
        for missing,color in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          p=box-{missing}
          if p<=cells: placements.append((p,color,1))
    by={p:[] for p in cells}
    for piece,color,size in placements:
      for p in piece: by[p].append((piece,color,size))
    for p in by: by[p].sort(key=lambda x:(-x[2],x[1]))
    def cover(rem):
      if not rem:return []
      p=min(rem)
      for piece,color,_ in by[p]:
        if piece<=rem:
          rest=cover(rem-piece)
          if rest is not None:return [(piece,color)]+rest
      return None
    result=cover(cells)
    if result:
      for piece,color in result:
        for r,c in piece:out[r][c]=color
    return out
